interface Stream { read(): string }
class FileStream implements Stream { read(){ return 'file' } }
class StreamDecorator implements Stream {
  constructor(protected stream: Stream) {}
  read(){ return this.stream.read() }
}
class CompressionDecorator extends StreamDecorator { read(){ return compress(super.read()) } }

interface Notifier { send(msg: string): void }
class BaseNotifier implements Notifier { send(m){ /* deliver */ } }
class NotifierDecorator implements Notifier { constructor(protected inner: Notifier){}
  send(m){ this.inner.send(m) }
}
class LoggingDecorator extends NotifierDecorator { send(m){ console.log(m); super.send(m) } }

// Version A: Composition via wrappers
interface Service { handle(req: string): string }
class CoreService implements Service { handle(r:string){ return 'ok:'+r } }
class LoggingDecorator implements Service { constructor(private s: Service){}
  handle(r:string){ console.log(r); return this.s.handle(r) }
}
class CachingDecorator implements Service { constructor(private s: Service, private cache=new Map()){}
  handle(r:string){ if(this.cache.has(r)) return this.cache.get(r); const res=this.s.handle(r); this.cache.set(r,res); return res }
}

// Version B: Subclassing combinations
class CoreV2 { handle(r:string){ return 'ok:'+r } }
class LoggingService extends CoreV2 { handle(r:string){ console.log(r); return super.handle(r) } }
class CachingLoggingService extends LoggingService { handle(r:string){ /* duplicate caching logic */ return super.handle(r) } }
